// RuneAt returns the n-th rune of s, counting from 0, or false if out of range.
func RuneAt(s string, n int) (r rune, ok bool) {
	if n < 0 || n >= utf8.RuneCountInString(s) {
		return 0, false
	}
	r, _ = utf8.DecodeRuneInString(s)
	for i := 1; i <= n; i++ {
