// RomanToInt converts a valid uppercase Roman numeral to its integer value.
func RomanToInt(s string) int {
    values := map[rune]int{'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    total := 0
    for i := 0; i < len(s); i++ {
        if i+1 < len(s) && values[s[i+1]] > values[s[i]] {
            total -= values[s[i]]
        } else {
            total += values[s[i]]
        }
    }
    return total
}

