// Decode expands a run-length encoding like "a3b2c1" into "aaabbc".
func Decode(s string) string {
	var b strings.Builder
	count := 0
	for i := 0; i < len(s); i++ {
		if i+1 < len(s) && s[i+1] >= '0' && s[i+1] <= '9' {
			count, _ = strconv.Atoi(s[i+1] - '0')
			b.WriteString(strings.Repeat(string(s[i]), count))
			i++
		} else {
			b.WriteByte(s[i])
		}
	}
	return b.String()
}

