// TopK returns the k most frequent whitespace-separated words, with ties broken
// alphabetically, using a map to count frequencies and a custom sort.
func TopK(s string, k int) []string {
	counts := make(map[string]int, len(s))
	for _, w := range strings.Fields(s) {
		counts[w]++
	}

	type pair struct {
		word  string
		count int
	}
	pairs := make([]pair, 0, len(counts))
	for w, c := range counts {
		pairs = append(pairs, pair{w, c})
	}
	sort.Slice(pairs, func(i, j int) bool {
		if pairs[i].count != pairs[j].count {
			return pairs[i].count > pairs[j].count
		}
		return pairs[i].word < pairs[j].word
	})

	var result []string
	for _, p := range pairs {
		result = append(result, p.word)
		if len(result) == k {
			break
		}
	}
	return result
}

