type Ring struct {
	buf  []int
	head int
	n    int
}

func NewRing(cap int) *Ring {
	return &Ring{buf: make([]int, cap)}
}

func (r *Ring) Push(v int) {
	if r.n < len(r.buf) {
		r.buf[r.n] = v
		r.n++
	} else {
		r.buf[r.head] = v
		r.head = (r.head + 1) % len(r.buf)
	}
}

func (r *Ring) Items() []int {
	if r.n == 0 {
		return nil
	}
	items := make([]int, r.n)
	copy(items, r.buf[r.head:])
	copy(items[len(r.buf)-r.n:], r.buf[:r.head])
	return items
}

