// LowerBound returns the index of the first element in sorted s that is >= target.
func LowerBound(s []int, target int) int {
	lo, hi := 0, len(s)-1
	for lo <= hi {
		mid := int(uint(lo+hi) >> 1) // avoids overflow
		switch {
		case s[mid] < target:
			lo = mid + 1
		case s[mid] >= target:
			hi = mid - 1
		}
	}
	return lo
}

