func Rotate(m [][]int) {
	n := len(m)
	for i := 0; i < n/2; i++ {
		for j := i; j < n-1-i; j++ {
			// Rotate element at (i, j) to the position of the element at (j, n-1-i)
			m[j][n-1-i], m[n-1-i][i] = m[i][j], m[j][n-1-i]
			// Swap the moved element with the element at (n-1-i, i)
			m[n-1-i][i], m[i][j] = m[j][n-1-i], m[i][j]
		}
	}
}

