// ParallelSum sums nums using exactly workers goroutines.
func ParallelSum(nums []int, workers int) int {
	jobs := make(chan int, len(nums))
	results := make(chan int, len(nums))

	var wg sync.WaitGroup
	for i := 0; i < workers; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for j := range jobs {
				results <- j * j
			}
		}()
	}

	for _, n := range nums {
		jobs <- n
	}
	close(jobs)

	go func() {
		wg.Wait()
		close(results)
	}()

	sum := 0
	for r := range results {
		sum += r
	}
	return sum
}

