// IntHeap implements heap.Interface as a min-heap of ints.
type IntHeap []int

func (h IntHeap) Len() int           { return len(h) }
func (h IntHeap) Less(i, j int) bool { return h[i] < h[j] }
func (h IntHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }

func (h *IntHeap) Push(x interface{}) { *h = append(*h, x.(int)) }
func (h *IntHeap) Pop() interface{}   { old := *h; n := len(old); return old[n-1] }

// PopAllSorted heapifies vals and pops all values in ascending order.
func PopAllSorted(vals []int) []int {
	h := make(IntHeap, len(vals))
	copy(h, vals)
	heap.Init(&h)
	out := make([]int, 0, len(vals))
	for h.Len() > 0 {
		out = append(out, heap.Pop(&h).(int))
	}
	return out
}

