// CountUntil consumes ints from ch and returns how many it received when ctx is cancelled or ch is closed.
func CountUntil(ctx context.Context, ch <-chan int) int {
	count := 0
	for {
		select {
		case <-ctx.Done(): // ctx cancelled or timed out
			return count
		case v, ok := <-ch:
			if !ok { // channel closed
				return count
			}
			count++
		}
	}
}

