// ReadChunks reads r fully and splits the bytes into chunks of at most size.
func ReadChunks(r io.Reader, size int) ([][]byte, error) {
	var chunks [][]byte
	buf := new(bytes.Buffer)
	for {
		b := make([]byte, size)
		n, err := r.Read(b)
		if err == io.EOF {
			break
		}
		if err != nil {
			return nil, err
		}
		buf.Write(b[:n])
		if buf.Len() >= size {
			chunks = append(chunks, buf.Bytes())
			buf.Reset()
		}
	}
	if buf.Len() > 0 {
		chunks = append(chunks, buf.Bytes())
	}
	return chunks, nil
}

